#!/usr/bin/env bash
# Crea etiquetas, milestones e issues del MVP de StockScan en el repositorio actual.
# Requiere GitHub CLI (gh) con sesión iniciada. Ejecutar dentro del repo: bash docs/crear-issues.sh
set -e
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
echo "Creando en $REPO"

# Etiquetas
gh label create "ui" --color 1d76db --force >/dev/null
gh label create "datos" --color 5319e7 --force >/dev/null
gh label create "lógica" --color fbca04 --force >/dev/null
gh label create "pruebas" --color 0e8a16 --force >/dev/null
gh label create "integración" --color d93f0b --force >/dev/null
gh label create "tarea" --color cfd3d7 --force >/dev/null
gh label create "mejora" --color a2eeef --force >/dev/null

# Milestones
gh api "repos/$REPO/milestones" -f title="Fase 1 — Estructura base y navegación" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 2 — Productos y escáner" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 3 — Ventas y movimientos" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 4 — Alertas y cierre diario" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true
gh api "repos/$REPO/milestones" -f title="Fase 5 — Exportación CSV" -f description="Ver docs/ROADMAP.md" >/dev/null 2>&1 || true

# Issues
gh issue create --title "[F1-T1] Crear el proyecto Expo con TypeScript y Expo Router" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2.5 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "tarea" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
gh issue create --title "[F1-T2] Alinear versiones y herramientas con los repos hermanos" --body "$(printf 'Fase 1 — Estructura base y navegación\nHistorias: —\nEstimación: 2.5 h\n\nVer docs/PLANNING.md y docs/SPEC.md.\n\nCriterios:\n- [ ] Definición de terminado cumplida (lint, tipos, tests, modo avión).')" --label "tarea" --milestone "Fase 1 — Estructura base y navegación" >/dev/null
